fn bench_daitch_mokotoff(c: &mut Criterion) {
    let names = load_names();
    let scales = batches(&names);

    let verbora = DaitchMokotoff::new();
    // Constructed ONCE, outside the timing loops: `default()` parses the
    // embedded commons-codec `dmrules.txt` with a `nom` grammar — a real
    // construction cost Verbora's static-table `new()` does not have. See
    // the module doc comment's Daitch-Mokotoff section for why that
    // asymmetry is disclosed rather than timed.
    let rphonetic = DaitchMokotoffSoundex::default();

    let mut g = c.benchmark_group("daitch_mokotoff");
    for (label, elements, batch) in &scales {
        g.throughput(Throughput::Elements(*elements));
        g.bench_with_input(BenchmarkId::new("verbora", label), batch, |b, batch| {
            b.iter(|| {
                let mut total = 0usize;
                for w in black_box(batch.as_slice()) {
                    total += verbora.process(black_box(w)).len();
                }
                black_box(total)
            });
        });
        // `.soundex()`, never `.encode()` — the exact inverse of the
        // `dm_soundex` group's rule, because Verbora's branching `process`
        // returns the pipe-joined multi-branch codes byte-identically. See
        // the module doc comment's Daitch-Mokotoff section.
        g.bench_with_input(BenchmarkId::new("rphonetic", label), batch, |b, batch| {
            b.iter(|| {
                let mut total = 0usize;
                for w in black_box(batch.as_slice()) {
                    total += rphonetic.soundex(black_box(w)).len();
                }
                black_box(total)
            });
        });
    }
    g.finish();
}

/// Beider-Morse's own, smaller scales and shapes — see the module doc
/// comment's "Beider-Morse: its own, smaller scales and shapes" section for
/// why this doesn't reuse `batches()` and what the two 100-name shape
/// variants (`compound_100`, `prefixed_100`) each reveal.
fn beider_morse_batches(names: &[String]) -> Vec<(String, u64, Vec<String>)> {
    const SIZES: [usize; 7] = [1, 5, 10, 50, 100, 500, 1_000];
    const SHAPE_SIZE: usize = 100;
    let mut scales: Vec<(String, u64, Vec<String>)> = SIZES
        .iter()
        .map(|&n| {
            let batch = if n == 1 {
                vec![SINGLE_NAME.to_owned()]
            } else {
                names.iter().cloned().cycle().take(n).collect()
            };
            (n.to_string(), n as u64, batch)
        })
        .collect();
    scales.push((
        format!("compound_{SHAPE_SIZE}"),
        SHAPE_SIZE as u64,
        compound_names(names, SHAPE_SIZE),
    ));
    scales.push((
        format!("prefixed_{SHAPE_SIZE}"),
        SHAPE_SIZE as u64,
        prefixed_names(names, SHAPE_SIZE),
    ));
    scales
}

fn bench_beider_morse(c: &mut Criterion) {
    let names = load_names();
    let scales = beider_morse_batches(&names);

    let verbora = BeiderMorse::new(NameType::Generic, RuleType::Approx);
    // `embedded_bm`-only `Default`: "any"/"common" rules alone -- see the
    // module doc comment's "Beider-Morse: a coverage gap" section for why
    // this can never resolve a specific guessed language.
    let config_files = ConfigFiles::default();
    let rphonetic = BeiderMorseBuilder::new(&config_files).build();

    let mut g = c.benchmark_group("beider_morse");
    for (label, elements, batch) in &scales {
        g.throughput(Throughput::Elements(*elements));
        g.bench_with_input(BenchmarkId::new("verbora", label), batch, |b, batch| {
            b.iter(|| {
                let mut total = 0usize;
                for w in black_box(batch.as_slice()) {
                    total += verbora.encode(black_box(w)).spellings.len();
                }
                black_box(total)
            });
        });
        g.bench_with_input(BenchmarkId::new("rphonetic", label), batch, |b, batch| {
            b.iter(|| {
                let mut total = 0usize;
                for w in black_box(batch.as_slice()) {
                    total += rphonetic.encode(black_box(w)).len();
                }
                black_box(total)
            });
        });
    }
    g.finish();
}

